public async Task<bool> VerifyRecaptchaAsync(string token, string remoteIp)
{
    var secret = _configuration["Recaptcha:SecretKey"];
    var client = new HttpClient();
    var response = await client.PostAsync(
        $"https://www.google.com/recaptcha/api/siteverify?secret={secret}&response={token}&remoteip={remoteIp}",
        null);

    var json = await response.Content.ReadAsStringAsync();
    var result = JsonSerializer.Deserialize<RecaptchaResponse>(json);

    return result != null && result.Success && result.Score >= 0.5;
}

[HttpPost("login")]
public async Task<IActionResult> Login(LoginRequest request)
{
    var isValidCaptcha = await VerifyRecaptchaAsync(
        request.CaptchaToken, HttpContext.Connection.RemoteIpAddress?.ToString() ?? "");

    if (!isValidCaptcha)
    {
        ModelState.AddModelError("", "Please complete the CAPTCHA.");
        return BadRequest(ModelState);
    }

